Group {
                Button("Commit...") {
                    // TODO: Open Source Control Navigator to Changes tab
                }
                .disabled(true)

                Button("Push...") {
                    sourceControlManager?.pushSheetIsPresented = true
                }

                Button("Pull...") {
                    sourceControlManager?.pullSheetIsPresented = true
                }
                .keyboardShortcut("x", modifiers: [.command, .option])

                Button("Fetch Changes") {
                    sourceControlManager?.fetchSheetIsPresented = true
                }

                Divider()

                Button("Stage All Changes") {
                    guard let sourceControlManager else { return }
                    if sourceControlManager.changedFiles.isEmpty {
                        sourceControlManager.noChangesToStageAlertIsPresented = true
                    } else {
                        Task {
                            do {
                                try await sourceControlManager.add(sourceControlManager.changedFiles.map { $0.fileURL })
                            } catch {
                                await sourceControlManager.showAlertForError(
                                    title: "Failed To Stage Changes",
                                    error: error
                                )
                            }
                        }
                    }
                }

                Button("Unstage All Changes") {
                    guard let sourceControlManager else { return }
                    if sourceControlManager.changedFiles.isEmpty {
                        sourceControlManager.noChangesToUnstageAlertIsPresented = true
                    } else {
                        Task {
                            do {
                                try await sourceControlManager.reset(
                                    sourceControlManager.changedFiles.map { $0.fileURL }
                                )
                            } catch {
                                await sourceControlManager.showAlertForError(
                                    title: "Failed To Unstage Changes",
                                    error: error
                                )
                            }
                        }
                    }
                }

                Divider()

                Button("Cherry-Pick...") {
                    // TODO: Implementation Needed
                }
                .disabled(true)

                Button("Stash Changes...") {
                    if sourceControlManager?.changedFiles.isEmpty ?? false {
                        sourceControlManager?.noChangesToStashAlertIsPresented = true
                    } else {
                        sourceControlManager?.stashSheetIsPresented = true
                    }
                }

                Divider()

                Button("Discard All Changes...") {
                    if sourceControlManager?.changedFiles.isEmpty ?? false {
                        sourceControlManager?.noChangesToDiscardAlertIsPresented = true
                    } else {
                        sourceControlManager?.discardAllAlertIsPresented = true
                    }
                }

                Divider()

                Button("Add Exisiting Remote...") {
                    sourceControlManager?.addExistingRemoteSheetIsPresented = true
                }
            }
            .disabled(windowController?.workspace == nil)

SettingsForm {
            Section {
                LabeledContent("Account") {
                    Text(currentAccount.name)
                }
                TextField("Description", text: $currentAccount.description)
                if currentAccount.provider.baseURL == nil {
                    TextField("Server", text: $currentAccount.serverURL)
                }
            }

            Section {
                Picker(selection: $currentAccount.urlProtocol) {
                    Text("HTTPS")
                        .tag(SourceControlAccount.URLProtocol.https)
                    Text("SSH")
                        .tag(SourceControlAccount.URLProtocol.ssh)
                } label: {
                    Text("Clone Using")
                    Text("New repositories will be cloned from \(currentAccount.provider.name)"
                         + " using \(currentAccount.urlProtocol.rawValue).")
                }
                .pickerStyle(.radioGroup)
                if currentAccount.urlProtocol == .ssh {
                    Picker("SSH Key", selection: $currentAccount.sshKey) {
                        Text("None")
                            .tag("")
                        Divider()
                        if let sshPath = FileManager.default.homeDirectoryForCurrentUser.appending(
                            path: ".ssh",
                            directoryHint: .isDirectory
                        ) as URL? {
                            if let files = try? FileManager.default.contentsOfDirectory(
                                atPath: sshPath.path
                            ) {
                                ForEach(files, id: \.self) { filename in
                                    let fileURL = sshPath.appending(path: filename)
                                    if let contents = try? String(contentsOf: fileURL) {
                                        if isPublicSSHKey(contents) {
                                            Text(filename.replacingOccurrences(of: ".pub", with: ""))
                                                .tag(fileURL.path)
                                        }
                                    }
                                }
                                Divider()
                            }
                        }
                        Text("Create New...")
                            .tag("CREATE_NEW")
                        Text("Choose...")
                            .tag("CHOOSE")
                    }
                    .onReceive([currentAccount.sshKey].publisher.first()) { value in
                        if value == "CREATE_NEW" {
                            print("Create a new ssh key...")
                            createSshKeyIsPresented = true
                            currentAccount.sshKey = prevSshKey
                        } else if value == "CHOOSE" {
                            print("Choose a ssh key...")
                            currentAccount.sshKey = prevSshKey
                        } else {
                            // TODO: Validate SSH key and check if it is uploaded to git provider.
                            // If not provide button to do so
                        }
                        prevSshKey = currentAccount.sshKey
                    }
                    .sheet(isPresented: $createSshKeyIsPresented, content: { CreateSSHKeyView() })
                }
            } footer: {
                HStack {
                    Button("Delete Account...") {
                        deleteConfirmationIsPresented.toggle()
                    }
                    .alert(
                        Text("Are you sure you want to delete the account “\(account.description)”?"),
                        isPresented: $deleteConfirmationIsPresented
                    ) {
                        Button("OK") {
                            // Handle the account delete
                            handleAccountDelete()
                            dismiss()
                        }
                        Button("Cancel") {
                            // Handle the cancel, dismiss the alert
                            deleteConfirmationIsPresented.toggle()
                        }
                    } message: {
                        Text("Deleting this account will remove it from CodeEdit.")
                    }

                    Spacer()
                }
                .padding(.top, 10)
            }
        }
        .onChange(of: currentAccount) { _, newValue in
            account = newValue
        }
        .navigationTitle(currentAccount.description)

Circle()
            .stroke(style: StrokeStyle(lineWidth: lineWidth))
            .foregroundStyle(.tertiary)
            .overlay {
                if let progress = progress {
                    Circle()
                        .trim(from: 0, to: progress)
                        .stroke(Color.accentColor, style: StrokeStyle(lineWidth: lineWidth, lineCap: .round))
                        .animation(.easeInOut, value: progress)
                } else {
                    Circle()
                        .trim(from: 0, to: 0.5)
                        .stroke(Color.accentColor, style: StrokeStyle(lineWidth: lineWidth, lineCap: .round))
                        .rotationEffect(
                            previousValue ?
                                .degrees(isAnimating ?  0 : -360)
                            : .degrees(isAnimating ? 360 : 0)
                        )
                        .animation(Animation.linear(duration: 1).repeatForever(autoreverses: false), value: isAnimating)
                        .onAppear {
                            self.previousValue = isAnimating
                            self.isAnimating.toggle()
                        }
                }
            }
            .rotationEffect(.degrees(-90))
            .padding(lineWidth/2)
            .overlay {
                if currentTaskCount > 1 {
                    Text("\(currentTaskCount)")
                        .font(.caption)
                }
            }
            .accessibilityElement()
            .accessibilityAddTraits(.updatesFrequently)

Group {
            if #available(macOS 26, *) {
                content
                    .fixedSize(horizontal: false, vertical: false)
                    .padding(5)
                // TaskNotificationView doesn't have it's own padding
                // Also this padding seems weird. However, we want the spinning circle to be padded with the same
                // amount from both the top and bottom, as well as the trailing edge. So despite it not being exactly
                // the same it *looks* correctly padded
                    .padding(.trailing, 5)
                    .clipShape(Capsule())
                    .frame(minWidth: 200)
            } else {
                content
                    .fixedSize(horizontal: false, vertical: false)
                    .padding(.horizontal, 5)
                    .padding(.vertical, 1.5)
                    .frame(height: 22)
                    .clipped()
                    .background {
                        if colorScheme == .dark {
                            RoundedRectangle(cornerRadius: 5)
                                .opacity(0.1)
                        } else {
                            RoundedRectangle(cornerRadius: 5)
                                .opacity(0.1)
                        }
                    }
            }
        }
        .accessibilityElement(children: .contain)

